static class IntegrationTests {
 static Dictionary<string,object> A(params object[] p){var d=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)d.Add((string)p[i],p[i+1]);return d;}
 static Dictionary<string,object> O(object v){return Core.Json().Deserialize<Dictionary<string,object>>(Core.Json().Serialize(v));}
 static void Assert(bool b,string s){if(!b)throw new Exception(s);}
